bad_example:
std::vector<int> v = {1,2,3};
int& ref = v[0];
for (int i = 0; i < 1000; i++) v.push_back(i); // puede reallocar
std::cout << ref; // comportamiento indefinido: ref puede apuntar a memoria liberada

good_example:
std::vector<int> v = {1,2,3};
size_t idx = 0; // guardar el INDICE, no una referencia
for (int i = 0; i < 1000; i++) v.push_back(i);
std::cout << v[idx]; // seguro, v[idx] sigue siendo valido tras la realocacion

bad_example:
void procesar(Base b) { b.metodoVirtual(); } // b es una COPIA solo-Base
Derivada d;
procesar(d); // llama a Base::metodoVirtual, no a Derivada::metodoVirtual

good_example:
void procesar(const Base& b) { b.metodoVirtual(); }
Derivada d;
procesar(d); // ahora si se preserva el polimorfismo, llama a Derivada::metodoVirtual

bad_example:
int x = INT_MAX;
if (x + 1 < x) { /* 'deteccion' de overflow */ }
// UB: el compilador puede optimizar asumiendo que x+1 nunca desborda y eliminar el if entero

class Buffer {
  int* data;
 public:
  Buffer(size_t n) : data(new int[n]) {}
  ~Buffer() { delete[] data; } // solo el destructor
  // copy constructor y operator= generados por el compilador copian el PUNTERO, no el contenido
};

good_example:
class Buffer {
  std::unique_ptr<int[]> data;
 public:
  Buffer(size_t n) : data(std::make_unique<int[]>(n)) {}
  // destructor, move y (deleted) copy ya correctos automaticamente por unique_ptr
};

